[s1, h1] = sload('gdfs/ah7.20170613.161402.offline.mi.mi_bhbf.gdf');

% sample rate = 512 Hz
% 17 channels
%%
[s2, h2] = sload('gdfs/ah7.20170613.162331.offline.mi.mi_bhbf.gdf');

% sample rate = 512 Hz
% 17 channels
%%
[s3, h3] = sload('gdfs/ah7.20170613.162934.offline.mi.mi_bhbf.gdf');

% sample rate = 512 Hz
% 17 channels
%%
% Now that we know the files are all structured the same we can concatenate
N_GDFS = 3;
hs = cell(N_GDFS, 1);
hs{1} = h1;
hs{2} = h2;
hs{3} = h3;
%%
s = [s1; s2; s3];
sizes = [size(s1, 1); size(s2, 1); size(s3, 1)];
offsets = cumsum(sizes);
h = h1;

for i = 2:N_GDFS % 1 is already included
    h.EVENT.POS = [h.EVENT.POS; hs{i}.EVENT.POS + offsets(i-1)];
    h.EVENT.DUR = [h.EVENT.DUR; hs{i}.EVENT.DUR];
    h.EVENT.TYP = [h.EVENT.TYP; hs{i}.EVENT.TYP];
end
%%
trial = 0;
Tk = zeros(size(s, 1), 1);
Fk = zeros(size(s, 1), 1);
Ak = zeros(size(s, 1), 1);
CFk = zeros(size(s, 1), 1);
Xk = zeros(size(h.EVENT.POS, 1) / 4, 1);
Rk = zeros(size(s, 1), 1);

last_pos = 1;
for i = 1:size(sizes, 1)
    Rk(last_pos:offsets(i)) = i;
    last_pos = offsets(i) + 1;
end

for i = 1:size(h.EVENT.POS, 1)
    if i > 1 && Rk(h.EVENT.POS(i-1)) ~= Rk(h.EVENT.POS(i))
        trial = 0;
    end
    switch h.EVENT.TYP(i)
        case 1 % start
            startTrialIdx = h.EVENT.POS(i);
            trial = trial + 1;
        case 786 % fixation
            fixationStartIdx = h.EVENT.POS(i);
            fixationEndIdx = fixationStartIdx + h.EVENT.DUR(i) - 1;
            Fk(fixationStartIdx:fixationEndIdx) = h.EVENT.TYP(i);
        case 771 % cue (both feet)
            cueStartIdx = h.EVENT.POS(i);
            cueEndIdx = cueStartIdx + h.EVENT.DUR(i) - 1;
            Ak(cueStartIdx:cueEndIdx) = h.EVENT.TYP(i);
        case 773 % cue (both hand)
            cueStartIdx = h.EVENT.POS(i);
            cueEndIdx = cueStartIdx + h.EVENT.DUR(i) - 1;
            Ak(cueStartIdx:cueEndIdx) = h.EVENT.TYP(i);
        case 781 % feedback
            feedbackStartIdx = h.EVENT.POS(i);
            feedbackEndIdx = feedbackStartIdx + h.EVENT.DUR(i) - 1;
            CFk(feedbackStartIdx:feedbackEndIdx) = h.EVENT.TYP(i);
            Tk(startTrialIdx:feedbackEndIdx) = trial;
        otherwise
            error('Weird stuff in GDFs');
    end
end
%%
ax = subplot(1,1,1); %[output:166f2c98]
hold(ax, 'on'); %[output:166f2c98]
plot(Tk, 'DisplayName', 'Tk'); %[output:166f2c98]
plot(Rk, 'DisplayName', 'Rk'); %[output:166f2c98]
plot(Xk, 'DisplayName', 'Xk'); %[output:166f2c98]
hold(ax, 'off'); %[output:166f2c98]
legend(ax, 'show'); %[output:166f2c98]
%%
cla(ax); %[output:6a04ade8]
ax = subplot(1,1,1); %[output:6a04ade8]
hold(ax, 'on'); %[output:6a04ade8]
plot(Fk, 'DisplayName', 'Fk'); %[output:6a04ade8]
plot(Ak, 'DisplayName', 'Ak'); %[output:6a04ade8]
plot(CFk, 'DisplayName', 'CFk'); %[output:6a04ade8]
hold(ax, 'off'); %[output:6a04ade8]
legend(ax, 'show'); %[output:6a04ade8]
%%
offsets(end) - size(s, 1); % 0

total_size = 0;
for i = 1:N_GDFS
    total_size = total_size + size(hs{i}.EVENT.POS, 1);
end

total_size - size(h.EVENT.POS, 1); % 0
%%
eventColors = containers.Map('KeyType', 'double', 'ValueType', 'any');

cods = [001 771 773 781 786];

eventColors(001) = [0.90 0.20 0.20]; % red
eventColors(771) = [0.20 0.60 0.90]; % sky blue
eventColors(773) = [0.20 0.70 0.35]; % green
eventColors(781) = [0.65 0.35 0.80]; % purple
eventColors(783) = [0.95 0.60 0.15]; % orange
eventColors(786) = [0.15 0.75 0.75]; % turquoise
eventColors(897) = [0.80 0.45 0.55]; % pink
eventColors(898) = [0.55 0.45 0.25]; % brown
%%
START_PLOT = 115;
END_PLOT = 125;

interval = START_PLOT*512:END_PLOT*512;
x = interval ./ 512;

figure('Position', [100 100 1000 1000]); %[output:111eca9a]

for i = 1:3 %[output:group:5372f589]
    ax = subplot(3, 1, i); %[output:111eca9a]
    hold(ax, 'on')
    ylim(ax, [-80 80]);
    xlim(ax, [START_PLOT END_PLOT]);
    title(ax, sprintf("EEG Channel #%d in [%d,%d]s", i, START_PLOT, END_PLOT));
    xlabel(ax, 'seconds [s]');
    ylabel(ax, 'Amplitude [uV]');

    for j = 1:size(h.EVENT.POS, 1)
        start = h.EVENT.POS(j) / 512;
        term  = start + h.EVENT.DUR(j) / 512;
        code  = h.EVENT.TYP(j);

        if term < START_PLOT || start > END_PLOT
            continue
        end

        patch(ax, [start term term start], [-80 -80 80 80], ...
            eventColors(code), ...
            'FaceAlpha', 0.25, ...
            'EdgeColor', 'none', ...
            'HandleVisibility', 'off');

        xline(ax, start, 'k-');
        xline(ax, term, 'k-');

        p = zeros(size(cods,2),1);
        cods_idx = 1:size(cods,2);
        for k = cods_idx
            p(k) = patch(NaN, NaN, eventColors(cods(k)), ...
                'FaceAlpha', 0.25, 'EdgeColor', 'none', ...
                'DisplayName', int2str(cods(k)));
        end

        legend(p(cods_idx), 'Location', 'bestoutside');
    end

    plot(ax, x, s(interval, i), 'b', 'DisplayName', sprintf('Chn#%d', i));
    hold off;
end %[output:group:5372f589]
%%
START_PLOT = 235;
END_PLOT = 245;

interval = START_PLOT*512:END_PLOT*512;
x = interval ./ 512;

figure('Position', [100 100 1000 1000]); %[output:577eb233]

for i = 1:3 %[output:group:84947545]
    ax = subplot(3, 1, i); %[output:577eb233]
    hold(ax, 'on')
    ylim(ax, [-80 80]);
    xlim(ax, [START_PLOT END_PLOT]);
    title(ax, sprintf("EEG Channel #%d in [%d,%d]s", i, START_PLOT, END_PLOT));
    xlabel(ax, 'seconds [s]');
    ylabel(ax, 'Amplitude [uV]');

    for j = 1:size(h.EVENT.POS, 1)
        start = h.EVENT.POS(j) / 512;
        term  = start + h.EVENT.DUR(j) / 512;
        code  = h.EVENT.TYP(j);

        if term < START_PLOT || start > END_PLOT
            continue
        end

        patch(ax, [start term term start], [-80 -80 80 80], ...
            eventColors(code), ...
            'FaceAlpha', 0.25, ...
            'EdgeColor', 'none', ...
            'HandleVisibility', 'off');

        xline(ax, start, 'k-');
        xline(ax, term, 'k-');

        p = zeros(size(cods,2),1);
        cods_idx = 1:size(cods,2);
        for k = cods_idx
            p(k) = patch(NaN, NaN, eventColors(cods(k)), ...
                'FaceAlpha', 0.25, 'EdgeColor', 'none', ...
                'DisplayName', int2str(cods(k)));
        end

        legend(p(cods_idx), 'Location', 'bestoutside');
    end

    plot(ax, x, s(interval, i), 'b', 'DisplayName', sprintf('Chn#%d', i));
    hold off;
end %[output:group:84947545]

